e': None}], 'verification': {'what': 'test route success rate', 'how': 'monitor call completion', 'expected': 'success rate above threshold'}, 'rollback': {'trigger': 'route testing fails', 'action': 'recheck configurations', 'safety_guard': 'restore default settings', 'restores_state': ['initial test routes'], 'restoration_evidence': 'test call logs'}, 'risk_class': 'medium', 'blast_radius': 'medium', 'satisfies': None}, {'id': 'execute_cutover', 'description': 'Cutover by switching inbound DIDs to the new platform', 'action': 'cutover', 'target': 'inbound_DIDs', 'parallel_group': None, 'preconditions': [{'description': 'routes tested successfully', 'fact': 'routes_verified', 'established_by': 'test_routes', 'probe': None}], 'verification': {'what': 'call flow functionality', 'how': 'monitor call metrics', 'expected': 'calls routed correctly'}, 'rollback': {'trigger': 'cutover fails', 'action': 'reroute DIDs back to legacy PBX', 'safety_guard': 'confirm cutover status', 'restores_state': ['legacy DID routing'], 'restoration_evidence': 'verification of call routing'}, 'risk_class': 'critical', 'blast_radius': 'medium', 'satisfies': None}, {'id': 'monitor', 'description': 'Monitor call metrics post cutover', 'action': 'monitor_metrics', 'target': 'call_center', 'parallel_group': None, 'preconditions': [{'description': 'cutover executed', 'fact': 'DIDs_cut_over', 'established_by': 'execute_cutover', 'probe': None}], 'verification': {'what': 'call volume and quality', 'how': 'analyze metrics reports', 'expected': 'metrics within acceptable range'}, 'rollback': {'trigger': 'monitoring fails', 'action': 'revert to last known good metrics', 'safety_guard': 'confirm stability', 'restores_state': ['previous monitoring state'], 'restoration_evidence': 'history of call metrics'}, 'risk_class': 'medium', 'blast_radius': 'medium', 'satisfies': None}], 'dependencies': [{'from_task': 'dial_plan_rework', 'to_task': 'configure_routing_table', 'kind': 'hard', 'reason': ''}, {'from_task': 'configure_routing_table', 'to_task': 'test_routes', 'kind': 'hard', 'reason': ''}, {'from_task': 'test_routes', 'to_task': 'execute_cutover', 'kind': 'hard', 'reason': ''}, {'from_task': 'execute_cutover', 'to_task': 'monitor', 'kind': 'hard', 'reason': ''}], 'branches': []}

